// ════════════════════════════════════════════════════════
// PAGE 4: PPTX SLIDE VIEWER (Image-based)
// Shows pre-rendered PNG thumbnails of each slide.
// Thumbnails generated by gen_thumbs.py (LibreOffice)
// ════════════════════════════════════════════════════════

let EDITOR_CURRENT = 0;
let SLIDE_IMAGES = []; // Array of {src: dataUrl/objectUrl, slideNum}

function initEditor() {
  if (!SLIDES || SLIDES.length === 0) {
    document.getElementById('p4-empty').style.display = 'flex';
    document.getElementById('p4-content').style.display = 'none';
    return;
  }
  document.getElementById('p4-empty').style.display = 'none';
  document.getElementById('p4-content').style.display = 'flex';

  // If no pre-rendered images, try loading from thumbs/ folder
  if (SLIDE_IMAGES.length === 0) {
    loadThumbnails();
  } else {
    renderFilmstrip();
    navigateSlide(0, true);
  }
}

// ─── LOAD THUMBNAILS ───
// Try: 1) thumbs_16x9/ or thumbs_a3/ folder, 2) Extract from PPTX docProps
async function loadThumbnails() {
  SLIDE_IMAGES = [];
  const total = SLIDES.length;

  // Detect which template is active
  const info = document.getElementById('pptx-info')?.textContent || '';
  let thumbDir = 'thumbs'; // default
  if (info.includes('16:9') || info.includes('16x9')) thumbDir = 'thumbs_16x9';
  else if (info.includes('A3') || info.includes('a3')) thumbDir = 'thumbs_a3';

  // Try loading pre-rendered PNGs
  let loaded = 0;
  for (let i = 1; i <= total; i++) {
    try {
      const resp = await fetch(`${thumbDir}/slide_${i}.png`);
      if (resp.ok) {
        const blob = await resp.blob();
        SLIDE_IMAGES.push({ src: URL.createObjectURL(blob), slideNum: i });
        loaded++;
      } else {
        SLIDE_IMAGES.push({ src: '', slideNum: i });
      }
    } catch (e) {
      SLIDE_IMAGES.push({ src: '', slideNum: i });
    }
  }

  // If no pre-rendered thumbnails found, try extracting from PPTX
  if (loaded === 0 && PPTX_DATA) {
    await extractPptxImages();
  }

  renderFilmstrip();
  navigateSlide(0, true);

  if (loaded === 0) {
    showThumbsHint();
  }
}

// ─── EXTRACT IMAGES FROM PPTX (basic fallback) ───
async function extractPptxImages() {
  try {
    const zip = await JSZip.loadAsync(PPTX_DATA);

    // Try docProps/thumbnail.jpeg (overall thumbnail only)
    const thumbFile = zip.files['docProps/thumbnail.jpeg'];
    if (thumbFile) {
      const blob = await thumbFile.async('blob');
      // This is just the first slide thumbnail
      if (SLIDE_IMAGES[0]) SLIDE_IMAGES[0].src = URL.createObjectURL(blob);
    }

    // Extract all media images for reference
    // Map slide rels to find which images belong to which slide
    const slideFiles = Object.keys(zip.files)
      .filter(k => /^ppt\/slides\/slide\d+\.xml$/.test(k))
      .sort((a, b) => parseInt(a.match(/\d+/)[0]) - parseInt(b.match(/\d+/)[0]));

    for (let i = 0; i < slideFiles.length; i++) {
      const slideNum = parseInt(slideFiles[i].match(/\d+/)[0]);
      const relPath = `ppt/slides/_rels/slide${slideNum}.xml.rels`;
      const relsXml = zip.files[relPath] ? await zip.files[relPath].async('string') : '';

      // Find first image in this slide
      const imgRels = [...relsXml.matchAll(/Target="([^"]*\.(png|jpg|jpeg|gif))"/gi)];
      if (imgRels.length > 0 && SLIDE_IMAGES[i] && !SLIDE_IMAGES[i].src) {
        let target = imgRels[0][1].replace(/\\/g, '/');
        if (target.startsWith('../')) target = 'ppt/' + target.replace('../', '');
        const imgFile = zip.files[target];
        if (imgFile) {
          const blob = await imgFile.async('blob');
          SLIDE_IMAGES[i].src = URL.createObjectURL(blob);
        }
      }
    }
  } catch (e) {
    console.warn('[Viewer] Extract failed:', e);
  }
}

// ─── SHOW HINT TO GENERATE THUMBNAILS ───
function showThumbsHint() {
  const canvas = document.getElementById('slide-canvas');
  if (!canvas) return;
  canvas.innerHTML = `
    <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;text-align:center;padding:40px;color:#666">
      <div style="font-size:48px;margin-bottom:16px">📸</div>
      <div style="font-size:16px;font-weight:700;margin-bottom:8px">Chưa có ảnh preview slide</div>
      <div style="font-size:13px;line-height:1.6;max-width:500px">
        Chạy lệnh sau để tạo thumbnails:<br>
        <code style="display:block;margin:12px 0;padding:10px;background:#1e1e2e;color:#e0e0e0;border-radius:6px;font-size:12px;text-align:left">
          python gen_thumbs.py template_16x9.pptx thumbs_16x9<br>
          python gen_thumbs.py template_A3.pptx thumbs_a3
        </code>
        Sau đó refresh trang để xem slide preview.
      </div>
    </div>
  `;
}

// ─── RENDER SLIDE ───
function renderSlidePreview(idx) {
  const canvas = document.getElementById('slide-canvas');
  if (!canvas) return;

  const slideImg = SLIDE_IMAGES[idx];
  if (!slideImg || !slideImg.src) {
    canvas.innerHTML = `
      <div style="display:flex;align-items:center;justify-content:center;height:100%;color:#999">
        <span>Slide ${idx + 1} — chưa có ảnh preview</span>
      </div>`;
    canvas.style.background = '#f5f5f5';
    return;
  }

  canvas.style.background = '#000';
  canvas.innerHTML = `<img src="${slideImg.src}" style="width:100%;height:100%;object-fit:contain" alt="Slide ${idx + 1}">`;
}

// ─── FILMSTRIP ───
function renderFilmstrip() {
  const strip = document.getElementById('filmstrip');
  if (!strip) return;
  strip.innerHTML = '';

  const total = SLIDES.length;
  for (let i = 0; i < total; i++) {
    const slide = SLIDES[i];
    const img = SLIDE_IMAGES[i];
    const item = document.createElement('div');
    item.className = 'film-item' + (i === EDITOR_CURRENT ? ' active' : '');
    item.dataset.idx = i;
    item.onclick = () => navigateSlide(i, true);

    const preview = document.createElement('div');
    preview.className = 'film-preview';
    if (img && img.src) {
      preview.innerHTML = `<img src="${img.src}" style="width:100%;height:100%;object-fit:contain" alt="">`;
    } else {
      preview.innerHTML = `<span class="film-num">${i + 1}</span>`;
    }

    const label = document.createElement('div');
    label.className = 'film-label';
    label.textContent = slide?.title?.substring(0, 20) || 'Slide ' + (i + 1);

    item.appendChild(preview);
    item.appendChild(label);
    strip.appendChild(item);
  }
}

// ─── NAVIGATION ───
function navigateSlide(idx, absolute) {
  const total = SLIDES.length;
  if (total === 0) return;
  EDITOR_CURRENT = absolute ? idx : EDITOR_CURRENT + idx;
  if (EDITOR_CURRENT < 0) EDITOR_CURRENT = 0;
  if (EDITOR_CURRENT >= total) EDITOR_CURRENT = total - 1;

  renderSlidePreview(EDITOR_CURRENT);
  updateFilmstripActive();
  updateNavInfo();
}

function updateNavInfo() {
  const el = document.getElementById('editor-nav-info');
  if (el) el.textContent = `Slide ${EDITOR_CURRENT + 1} / ${SLIDES.length}`;
  const titleEl = document.getElementById('editor-slide-title');
  if (titleEl) titleEl.textContent = SLIDES[EDITOR_CURRENT]?.title || '';
}

function updateFilmstripActive() {
  document.querySelectorAll('.film-item').forEach(el => {
    el.classList.toggle('active', parseInt(el.dataset.idx) === EDITOR_CURRENT);
  });
  document.querySelector('.film-item.active')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function refreshEditor() {
  if (document.getElementById('p4')?.classList.contains('active')) {
    SLIDE_IMAGES = [];
    loadThumbnails();
  }
}

// ─── KEYBOARD ───
document.addEventListener('keydown', e => {
  if (!document.getElementById('p4')?.classList.contains('active')) return;
  if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); navigateSlide(-1, false); }
  else if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') { e.preventDefault(); navigateSlide(1, false); }
  else if (e.key === 'Home') { e.preventDefault(); navigateSlide(0, true); }
  else if (e.key === 'End') { e.preventDefault(); navigateSlide(SLIDES.length - 1, true); }
});
